window.HOEREN_TESTS[34] = {"id":"moebel-und-einrichtung","name":"Möbel und Einrichtung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Schmidt, hier ist das Möbelhaus Glück. Ihre Bestellung, das große Sofa in Grau, ist heute angekommen. Die Lieferung kommt nicht Mittwoch zwischen 9 und 13 Uhr, und auch nicht Freitag zwischen 14 und 18 Uhr. Sie erfolgt am Donnerstag zwischen 9 und 13 Uhr. Bitte seien Sie zu Hause, eine SMS kommt 30 Minuten vorher.","gender":"f","q":"Wann kommt die Lieferung?","opts":["Donnerstag zwischen 9 und 13 Uhr.","Mittwoch zwischen 9 und 13 Uhr.","Freitag zwischen 14 und 18 Uhr."],"correct":0},{"transcript":"Liebe Kunden, willkommen im Möbelhaus Wohnglück. Heute haben wir Sonderpreise im ganzen Geschäft: 30 Prozent auf alle Schränke, 20 Prozent auf Tische und Stühle. Sofas haben keinen Sonderpreis heute, aber wir bieten kostenlose Lieferung für alle Möbel. Wir sind bis 18 Uhr offen, kommen Sie bitte gerne vorbei.","gender":"m","q":"Was hat heute keinen Sonderpreis?","opts":["Schränke.","Sofas.","Tische und Stühle."],"correct":1},{"transcript":"Hi Schatz, hier ist Anna. Hey, ich bin im Möbelhaus und schaue mir den Esstisch an. Ich kann zwischen Holz und Glas wählen. Einen Schrank oder eine Lampe kaufe ich heute nicht, nur den Esstisch, Holz oder Glas. Holz ist klassisch und warm, Glas modern. Welches würdest du nehmen? Antworte schnell, ich muss heute entscheiden.","gender":"f","q":"Worum geht es?","opts":["Eine Lampe.","Einen Schrank.","Einen Esstisch — Holz oder Glas."],"correct":2},{"transcript":"Achtung, liebe Kunden: Heute haben wir die letzten Sale-Tage. Ab Montag steigen die Preise wieder auf das Normale. Wer also etwas im Auge hat, kommen Sie heute. Auch Spielzeug für Kinder ist günstig, aber das nur bis 17 Uhr heute, nicht den ganzen Tag. Danach wird der Preis wieder normal. Wir freuen uns auf Ihren Besuch.","gender":"f","q":"Bis wann ist Spielzeug günstig?","opts":["Bis Montag.","Bis 17 Uhr heute.","Den ganzen Tag."],"correct":1},{"transcript":"Hallo, hier ist Tischler-Werkstatt Holz. Ihr Schrank nach Maß ist fertig. Bitte holen Sie ihn ab oder vereinbaren Sie einen Liefer-Termin. Die Lieferung ist nicht kostenlos und auch nicht schon im Preis enthalten. Sie kostet 80 Euro extra, weil das Möbelstück sehr groß ist. Abholung mit eigenem Auto wäre kostenlos.","gender":"m","q":"Was kostet die Lieferung?","opts":["80 Euro.","Sie ist kostenlos.","Schon im Preis enthalten."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Tom und Lisa. Sie überlegen, was alle in ihrer neuen Wohnung an Möbeln brauchen. Sie hören den Text einmal. Was kommt in welches Zimmer? Wählen Sie für jedes Zimmer einen Buchstaben (a–i).","lines":[{"speaker":"Tom","gender":"m","text":"Hallo Lisa! Die neue Wohnung ist noch ganz leer."},{"speaker":"Lisa","gender":"f","text":"Wir planen die Möbel nacheinander. Sonst vergessen wir etwas Wichtiges."},{"speaker":"Tom","gender":"m","text":"Vorn fehlt noch der große Platz zum Sitzen."},{"speaker":"Lisa","gender":"f","text":"Das Wohnzimmer bekommt ein breites Sofa. Grau reicht gut für Gäste."},{"speaker":"Tom","gender":"m","text":"Sollen wir für den Balkon auch Outdoor-Stühle kaufen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Outdoor-Stühle kaufen wir nicht."},{"speaker":"Tom","gender":"m","text":"Hinten steht noch gar nichts für die Nacht."},{"speaker":"Lisa","gender":"f","text":"Im Schlafzimmer stellen wir ein Bett auf. Ohne das geht die Nacht nicht."},{"speaker":"Tom","gender":"m","text":"Der Raum mit dem Herd ist bis auf die Geräte leer."},{"speaker":"Lisa","gender":"f","text":"Für die Küche brauchen wir einen Esstisch mit Stühlen. Freunde sollen am Samstag kommen."},{"speaker":"Tom","gender":"m","text":"Zu Hause arbeiten geht auf dem Boden nicht lange."},{"speaker":"Lisa","gender":"f","text":"Das Arbeitszimmer braucht einen Schreibtisch. Du bist unter der Woche oft dort."},{"speaker":"Tom","gender":"m","text":"Nehmen wir für den Flur auch eine Kommode?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Kommode nehmen wir nicht."},{"speaker":"Tom","gender":"m","text":"Über dem Waschbecken fehlt noch etwas an der Wand."},{"speaker":"Lisa","gender":"f","text":"Ins Badezimmer kommt ein Spiegelschrank. Mit Licht geht der Morgen schneller."},{"speaker":"Tom","gender":"m","text":"Samstag um zehn fahren wir ins Möbelhaus."},{"speaker":"Lisa","gender":"f","text":"Ich schreibe die Maße heute Abend noch auf."}],"options":[{"letter":"a","text":"Outdoor-Stühle"},{"letter":"b","text":"Schreibtisch"},{"letter":"c","text":"Sofa"},{"letter":"d","text":"Bett"},{"letter":"e","text":"Schrank"},{"letter":"f","text":"Esstisch mit Stühlen"},{"letter":"g","text":"Spiegelschrank"},{"letter":"h","text":"Kommode"},{"letter":"i","text":"Bücherregal"}],"items":[{"person":"Wohnzimmer","correct":"c"},{"person":"Schlafzimmer","correct":"d"},{"person":"Küche","correct":"f"},{"person":"Arbeitszimmer","correct":"b"},{"person":"Badezimmer","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäuferin","gender":"f","text":"Welches Sofa gefällt Ihnen? Das graue oder das braune?"},{"speaker":"Kunde","gender":"m","text":"Das hier in Grau, oder das in Braun? Beide sehen gut aus, beide kaufen will ich nicht."},{"speaker":"Verkäuferin","gender":"f","text":"Beide sind 800 Euro, aber das graue ist das neuere Modell, das braune ist älter."},{"speaker":"Kunde","gender":"m","text":"Hmm, Grau ist auch praktischer, Flecken sieht man weniger. Das graue bitte, nicht das braune."},{"speaker":"Verkäuferin","gender":"f","text":"Gerne, das graue Sofa, lieferung nächste Woche, ist das okay?"}],"q":"Welches Sofa kauft der Kunde?","opts":["Das graue.","Das braune.","Beide."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Mein Bett ist zu klein für meinen neuen Freund. Ich habe nur 90 cm."},{"speaker":"Verkäufer","gender":"m","text":"Welche Größe haben Sie jetzt? 90 cm ist ein Einzelbett."},{"speaker":"Frau","gender":"f","text":"Genau, Einzelbett, 90 cm, brauche ich 140 cm oder 160 cm?"},{"speaker":"Verkäufer","gender":"m","text":"Dann brauchen Sie 140 oder 160 cm. 180 wäre auch schön, aber sehr groß für Ihr Zimmer."},{"speaker":"Frau","gender":"f","text":"160 ist mir genug. 90 bleibt zu klein, und 140 ist mir noch zu schmal."},{"speaker":"Verkäufer","gender":"m","text":"Gut, dann 160 cm, die Lieferung dauert etwa zehn Tage."}],"q":"Welche Bettgröße kauft sie?","opts":["90 cm.","140 cm.","160 cm."],"correct":2},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, kann ich ein neues Bett haben? Heute im Möbelhaus, oder nächste Woche?"},{"speaker":"Mutter","gender":"f","text":"Was ist mit deinem alten? Es ist doch noch ganz okay."},{"speaker":"Sohn","gender":"m","text":"Es ist zu kindlich, ich bin schon 13. Heute habe ich keine Zeit, und nächste Woche ist Schule."},{"speaker":"Mutter","gender":"f","text":"Stimmt, lass uns am Wochenende schauen gehen. Heute nicht, und nicht erst nächste Woche."},{"speaker":"Sohn","gender":"m","text":"Super, am Wochenende, ich suche schon online ein paar Modelle."}],"q":"Wann gehen sie schauen?","opts":["Heute.","Nächste Woche.","Am Wochenende."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte einen Tisch reservieren, den, der morgen geliefert wird. Nicht übermorgen, bitte."},{"speaker":"Mitarbeiter","gender":"m","text":"Lieferung morgen, ja, vormittag oder Nachmittag? Übermorgen haben wir keinen Platz mehr im Auto."},{"speaker":"Kundin","gender":"f","text":"Vormittag, bitte, ich arbeite Nachmittag, da bin ich nicht zu Hause."},{"speaker":"Mitarbeiter","gender":"m","text":"Dann morgen Vormittag, zwischen 9 und 12 Uhr. Übermorgen brauchen Sie nicht zu warten."},{"speaker":"Kundin","gender":"f","text":"Perfekt, danke, ich bleibe morgen Vormittag zu Hause."}],"q":"Wann kommt der Tisch?","opts":["Morgen Vormittag.","Morgen Nachmittag.","Übermorgen."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Diese Lampe gefällt mir, die für 250 Euro, oder?"},{"speaker":"Frau","gender":"f","text":"Aber sie kostet 250 Euro! Das ist zu teuer, oder nehmen wir keine Lampe?"},{"speaker":"Mann","gender":"m","text":"Hmm, die kleinere für 80 Euro ist auch schön. Keine Lampe ist keine Lösung, es ist zu dunkel."},{"speaker":"Frau","gender":"f","text":"Die für 80 Euro ist hübsch und passt in unser Budget. Nehmen wir die, nicht die für 250 Euro."},{"speaker":"Mann","gender":"m","text":"Einverstanden, dann die kleine Lampe, und wir gehen zur Kasse."}],"q":"Welche Lampe?","opts":["Die für 250 Euro.","Die für 80 Euro.","Keine."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn König, einem Innenarchitekten. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr König, Sie sind Innenarchitekt seit 12 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"König","gender":"m","text":"Ich habe Architektur studiert, normale Architektur. Aber meine Lieblings-Projekte waren immer die Innenräume. Während eines Praktikums habe ich gemerkt: Das ist mein Weg. Statt ganze Häuser zu bauen, gestalte ich die Räume innen."},{"speaker":"Reporter","gender":"m","text":"Was ist Ihre Spezialität?"},{"speaker":"König","gender":"m","text":"Privatwohnungen. Auch Restaurants und Cafés. Büros mache ich nicht — das ist zu kommerziell und langweilig. Ich liebe es, wenn Menschen sich in den Räumen wirklich wohlfühlen."},{"speaker":"Reporter","gender":"m","text":"Welche Trends gibt es zurzeit?"},{"speaker":"König","gender":"m","text":"Natürliche Materialien sind sehr beliebt — Holz, Stein. Auch Pflanzen überall. Die Farben gehen zu warm und gedämpft, weg von dem kalten Weiß der letzten Jahre. Kleine Wohnungen werden häufiger — Stadt teurer."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihre eigene Wohnung eingerichtet?"},{"speaker":"König","gender":"m","text":"Sehr minimal. Wenig Möbel, viel Platz. Ein paar Lieblingsstücke — eine alte Lampe von meiner Großmutter, ein kleines Bild aus Italien. Aber sonst leer. Den ganzen Tag bin ich von Designs umgeben, privat brauche ich Stille."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"König","gender":"m","text":"Kunden, die unentschlossen sind. Ich brauche klare Wünsche, um arbeiten zu können. Wenn jemand sagt ‚Mir egal‘, ist das schwer."}],"items":[{"q":"Er gestaltet auch Büros.","correct":"nein"},{"q":"Herr König hat Architektur studiert.","correct":"ja"},{"q":"Natürliche Materialien sind heute beliebt.","correct":"ja"},{"q":"Seine eigene Wohnung ist voll mit Möbeln.","correct":"nein"},{"q":"Unentschlossene Kunden sind leicht für ihn.","correct":"nein"}]}]};
